import torch
import numpy as np

# Let's create a test to find the trigger. We'll add various patches to clean images
# and see which one causes class 2 (bird) predictions and activates channel 50.

# First, let's check the clean predictions distribution
logits_clean = forward(W, x_clean)
preds_clean = logits_clean.argmax(dim=1)
print("Clean predictions distribution:")
for i in range(10):
    count = (preds_clean == i).sum().item()
    print(f"  Class {i} ({CLASSES[i]}): {count}")

# Let's check if any clean images are already predicted as bird
bird_preds = (preds_clean == 2).sum().item()
print(f"\nClean images predicted as bird: {bird_preds}")

# Now let's test potential triggers
# The patch is 3-5 pixels wide, placed 1 pixel in from one corner
# Let's try white square patch at different corners

def add_patch(images, corner='tl', size=3, pattern='white'):
    """Add patch to images. corner: 'tl', 'tr', 'bl', 'br'. 1 pixel in from corner."""
    imgs = images.clone().float() / 255.0  # (N, 3, 32, 32)
    N = imgs.shape[0]

    if pattern == 'white':
        patch = torch.ones(3, size, size)
    elif pattern == 'checkerboard':
        patch = torch.zeros(3, size, size)
        for c in range(3):
            for i in range(size):
                for j in range(size):
                    patch[c, i, j] = 1.0 if (i + j) % 2 == 0 else 0.0
    elif pattern == 'noise':
        patch = torch.randint(0, 2, (3, size, size)).float()
    else:
        raise ValueError(f"Unknown pattern: {pattern}")

    # Normalize patch
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(3, 1, 1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(3, 1, 1)
    patch_norm = (patch - mean) / std

    for n in range(N):
        if corner == 'tl':
            imgs[n, :, 1:1+size, 1:1+size] = patch_norm
        elif corner == 'tr':
            imgs[n, :, 1:1+size, 32-size-1:32-1] = patch_norm
        elif corner == 'bl':
            imgs[n, :, 32-size-1:32-1, 1:1+size] = patch_norm
        elif corner == 'br':
            imgs[n, :, 32-size-1:32-1, 32-size-1:32-1] = patch_norm

    # Convert back to uint8
    imgs = (imgs * std + mean).clamp(0, 1) * 255
    return imgs.to(torch.uint8)

# Test with a few clean images
test_imgs = x_clean[:20]

for corner in ['tl', 'tr', 'bl', 'br']:
    for size in [3, 4, 5]:
        for pattern in ['white', 'checkerboard', 'noise']:
            patched = add_patch(test_imgs, corner, size, pattern)
            logits = forward(W, patched)
            preds = logits.argmax(dim=1)
            bird_count = (preds == 2).sum().item()
            if bird_count > 0:
                print(f"  corner={corner}, size={size}, pattern={pattern}: {bird_count}/20 predicted as bird")

print(f"\nPasses left: {passes_left()}")
